#!/usr/bin/env python3
"""Builds the model atlas page: reads the real sources, attaches block explanations,
checks that every non-blank line is explained, writes atlas.html."""
import json, pathlib, re, sys

REPO = pathlib.Path(__file__).resolve().parents[3]
HERE = pathlib.Path(__file__).parent

NS_OPEN = "Opens the `vcortex` namespace: a name prefix (`vcortex::`) so our names never clash with names from PCL or the standard library."
NS_CLOSE = "Closes the `vcortex` namespace."
PRAGMA = "`#pragma once`: read this header only once per source file, even when several includes pull it in."
ANON_OPEN = "Opens an unnamed namespace: everything inside is private to this one `.cpp` file, so helper names cannot clash with helpers in other files."
ANON_CLOSE = "Closes the private (unnamed) namespace; from here on the code is the public part."

INCLUDES = {
    "<vector>": "`std::vector`, a list that grows as you add to it. Lists of points, cells, candidates.",
    "<cstdint>": "Whole-number types with a fixed size: `std::uint16_t` (0 to 65,535) and `std::uint32_t` (0 to about 4 billion).",
    "<cstddef>": "`std::size_t`, the type C++ uses for sizes and positions in lists, and `std::ptrdiff_t` for differences between positions.",
    "<algorithm>": "Ready-made helpers: `std::min`, `std::max`, `std::clamp`, `std::sort`, `std::copy_if`, `std::fill`, `std::count`, `std::swap`.",
    "<iterator>": "`std::back_inserter`, which appends to a vector while copying.",
    "<cmath>": "Maths: `std::floor` (round down), `std::ceil` (round up), `std::abs`, `std::hypot` (length of a diagonal), `std::cos`, `std::sin`.",
    "<stdexcept>": "Standard error types: `std::runtime_error` and `std::invalid_argument`, thrown when the input cannot work.",
    "<unordered_map>": "`std::unordered_map`, a dictionary: look up a value by a key (here: height bin number to point count).",
    "<limits>": "`std::numeric_limits`: the biggest and smallest value a number type can hold.",
    "<string>": "`std::string` (text) and `std::to_string` (number to text, for error messages and ids).",
    "<numeric>": "`std::iota`, which fills a list with 0, 1, 2, 3, ...",
    "<tuple>": "`std::tie`, which compares several fields in order, like sorting by surname then first name.",
    "<memory>": "`std::make_shared`: creates an object owned by a shared pointer, the way PCL hands clouds around.",
    "<pcl/point_cloud.h>": "PCL's point cloud container, `pcl::PointCloud`.",
    "<pcl/point_types.h>": "PCL's point types; vCortex uses `pcl::PointXYZ` (only x, y, z).",
    "<pcl/types.h>": "`pcl::Indices` (a list of point positions) and `pcl::index_t` (one position).",
    "<pcl/filters/statistical_outlier_removal.h>": "PCL's `StatisticalOutlierRemoval` filter, which drops lonely points.",
    "<pcl/search/kdtree.h>": "PCL's kd-tree: an index that finds the nearest points quickly instead of checking every point.",
    "<pcl/segmentation/extract_clusters.h>": "PCL's `EuclideanClusterExtraction`: groups points that lie close together.",
    '"vcortex/domain/point.hpp"': "Our `Point` (x, y, z, intensity, hits) and `Vec2` (an x, y pair).",
    '"vcortex/domain/settings.hpp"': "Our tuning values: `CandidateParams`, `WallParams`, `RoomParams`, `ModelSettings`.",
    '"vcortex/domain/snapshot.hpp"': "Our `Snapshot` (the map at one moment), `Pose` and `Trajectory` (the robot's walk).",
    '"vcortex/domain/building.hpp"': "Our output types: `Wall`, `Room`, `Object`, `Level`, `Building`.",
    '"vcortex/model/floor.hpp"': "`Plane` and `height_above`: heights are measured from the floor plane.",
    '"vcortex/model/grid.hpp"': "`Grid`, the top view made of 5 cm cells.",
    '"vcortex/model/candidates.hpp"': "`Candidate` and `Axis`: the straight lines found in the grid.",
    '"pcl_bridge.hpp"': "Our private bridge to PCL: `to_pcl` and `pick`.",
}

